<?php namespace App\Http\Controllers; use App\Http\Requests\ProductRequest; use App\Models\Product; use Illuminate\Http\Request; class ProductController extends Controller { public function index(Request $r){return Product::where('is_active',true)->when($r->category,fn($q,$c)=>$q->where('category',$c))->when($r->search,fn($q,$s)=>$q->where(fn($x)=>$x->where('name','like','%'.$s.'%')->orWhere('description','like','%'.$s.'%')))->when($r->min_price,fn($q,$p)=>$q->where('price','>=',$p))->when($r->max_price,fn($q,$p)=>$q->where('price','<=',$p))->orderBy($r->get('sort','name')==='price_asc'?'price':'name')->paginate(24);} public function show(Product $product){return $product;} public function store(ProductRequest $r){return Product::create($r->validated());} public function update(ProductRequest $r,Product $product){$product->update($r->validated());return $product;} public function destroy(Product $product){$product->delete();return response()->noContent();} }